typedef float time_value_t;

struct stringx {
    char data[8];
};

class timer_widget {
public:
    class timer_func {
    public:
        time_value_t time;
        stringx function;
    };

    template<class T> class vector {
        T *start;
        T *finish;
        T *end_of_storage;
    public:
        typedef T *iterator;
        iterator begin() { return start; }
        iterator end() { return finish; }
        iterator erase(iterator position);
    };

private:
    char padding[0x1a4];
    vector<timer_func> script_calls_left;
    vector<timer_func> script_calls_made;

public:
    void remove_script_function(time_value_t start, time_value_t end);
};

void timer_widget::remove_script_function(time_value_t start, time_value_t end)
{
  vector<timer_func>::iterator sci = script_calls_made.begin();
  while(sci != script_calls_made.end())
  {
    if((*sci).time >= start && (*sci).time <= end)
      sci = script_calls_made.erase(sci);
    else
      ++sci;
  }

  sci = script_calls_left.begin();
  while(sci != script_calls_left.end())
  {
    if((*sci).time >= start && (*sci).time <= end)
      sci = script_calls_left.erase(sci);
    else
      ++sci;
  }
}
